function fail(msg) {
  process.stderr.write(`Error: ${msg}\n`);
  process.exit(1);
}

function readVarInt(buf, offset) {
  if (offset < 0 || offset >= buf.length) {
    throw new Error(`incomplete varint at offset ${offset}`);
  }
  const first = buf[offset];
  if (first < 0xfd) {
    return { value: first, size: 1 };
  }
  if (first === 0xfd) {
    if (offset + 3 > buf.length) {
      throw new Error(`incomplete varint (0xfd) at offset ${offset}`);
    }
    return { value: buf.readUInt16LE(offset + 1), size: 3 };
  }
  if (first === 0xfe) {
    if (offset + 5 > buf.length) {
      throw new Error(`incomplete varint (0xfe) at offset ${offset}`);
    }
    return { value: buf.readUInt32LE(offset + 1), size: 5 };
  }
  // 0xff
  if (offset + 9 > buf.length) {
    throw new Error(`incomplete varint (0xff) at offset ${offset}`);
  }
  const big = buf.readBigUInt64LE(offset + 1);
  if (big > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error(`varint value ${big} exceeds max safe integer at offset ${offset}`);
  }
  return { value: Number(big), size: 9 };
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    fail('missing hex file path argument. Usage: node parse_tx.js <path_to_hex_file>');
  }

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    fail(`cannot read file "${filePath}": ${e.message}`);
    return;
  }

  // Strip whitespace (spaces, newlines, tabs, etc.)
  const hex = raw.replace(/\s+/g, '');

  if (hex.length === 0) {
    fail('empty hex string');
  }
  if (hex.length % 2 !== 0) {
    fail('malformed hex string: odd length');
  }
  if (!/^[0-9a-fA-F]*$/.test(hex)) {
    fail('malformed hex string: non-hex characters present');
  }

  let buf;
  try {
    buf = Buffer.from(hex, 'hex');
  } catch (e) {
    fail(`malformed hex string: ${e.message}`);
    return;
  }

  try {
    let offset = 0;

    function need(n) {
      if (offset + n > buf.length) {
        throw new Error(`incomplete transaction: need ${n} byte(s) at offset ${offset}, only ${buf.length - offset} remaining`);
      }
    }

    // Version (4 bytes LE)
    need(4);
    const version = buf.readInt32LE(offset);
    offset += 4;

    // Input count (VarInt)
    const ic = readVarInt(buf, offset);
    offset += ic.size;
    const inputCount = ic.value;

    const inputs = [];
    for (let i = 0; i < inputCount; i++) {
      // txid (32 bytes LE, reversed for display)
      need(32);
      const txidBytes = buf.slice(offset, offset + 32);
      const txid = Buffer.from(txidBytes).reverse().toString('hex').toLowerCase();
      offset += 32;

      // vout (4 bytes LE)
      need(4);
      const vout = buf.readUInt32LE(offset);
      offset += 4;

      // scriptsig length (VarInt)
      const sl = readVarInt(buf, offset);
      offset += sl.size;

      // scriptsig
      need(sl.value);
      const scriptsig = buf.slice(offset, offset + sl.value).toString('hex').toLowerCase();
      offset += sl.value;

      // sequence (4 bytes LE)
      need(4);
      const sequence = buf.readUInt32LE(offset);
      offset += 4;

      inputs.push({ txid, vout, scriptsig, sequence });
    }

    // Output count (VarInt)
    const oc = readVarInt(buf, offset);
    offset += oc.size;
    const outputCount = oc.value;

    const outputs = [];
    for (let i = 0; i < outputCount; i++) {
      // value (8 bytes LE)
      need(8);
      const valueBig = buf.readBigUInt64LE(offset);
      offset += 8;
      let value;
      if (valueBig <= BigInt(Number.MAX_SAFE_INTEGER)) {
        value = Number(valueBig);
      } else {
        // JSON numbers are doubles; preserve numeric value as best as possible.
        // Use Number conversion (may lose precision for values > 2^53-1).
        value = Number(valueBig);
      }

      // scriptpubkey length (VarInt)
      const pl = readVarInt(buf, offset);
      offset += pl.size;

      // scriptpubkey
      need(pl.value);
      const scriptpubkey = buf.slice(offset, offset + pl.value).toString('hex').toLowerCase();
      offset += pl.value;

      outputs.push({ value, scriptpubkey });
    }

    // Locktime (4 bytes LE)
    need(4);
    const locktime = buf.readUInt32LE(offset);
    offset += 4;

    if (offset !== buf.length) {
      throw new Error(`malformed transaction: ${buf.length - offset} trailing byte(s) after locktime`);
    }

    const result = {
      version,
      input_count: inputCount,
      inputs,
      output_count: outputCount,
      outputs,
      locktime,
    };

    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
  } catch (e) {
    fail(e.message);
  }
}

